CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "ab04d749-0a82-40c2-9a6c-22bcd0ab5c9a",
  "snapshot_timestamp": "2026-05-21T21:56:19Z",
  "ticket_id": "97fc-b2ca",
  "items": [
    {
      "original_text": "A commit touching >=20 files (excluding .test-index) is automatically diverted from REVIEW-WORKFLOW.md into a new REVIEW-WORKFLOW-HUGE.md without any manual intervention",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior where commits meeting size criteria are automatically routed to a specific workflow, not a one-time migration task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "REVIEW-WORKFLOW-HUGE identifies confirmed refactors by sampling 7 stratified files and requiring >=5/7 to show a consistent transformation pattern; confirmed refactors proceed through haiku batch agents + a new refactor-anomaly opus reviewer that checks only flagged anomalous files",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability for identifying and processing refactors through a specific workflow pattern that persists after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Non-refactor large commits (pattern confidence below threshold) return to the standard review path; before dispatching any sub-agent the workflow emits a MODEL_OVERRIDE: opus signal, and all tier sub-agents are instantiated with the opus model regardless of classifier tier; the final findings file is identical in schema to the standard review path output",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior and routing logic that persists after implementation, not a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When a diff exceeds 600 lines the classifier appends SIZE_WARNING: <line_count> lines to its output and continues processing; no diff is ever returned with REJECTED status solely due to line count; verifiable by staging a 700-line commit and asserting the workflow produces a findings file with no rejection status",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (classifier's handling of large diffs) that persists after implementation, despite the testability language"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The refactor-anomaly opus reviewer emits a structured findings block with one entry per anomalous file, each carrying a dimension label (pattern_conformance | behavioral_drift | callsite_completeness), a severity (critical | important | minor), and a description; the review is considered passing when no critical findings are present",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability and output structure that persists after implementation, with a defined passing condition"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": ".test-index is excluded from the file count threshold check",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior/configuration where the test index is continuously excluded from the threshold check"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The diversion threshold is configurable via review.huge_diff_file_threshold (default: 20, must be a positive integer) in dso-config.conf; setting 0 or a negative integer is rejected with a validation error at threshold-check time",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system capability where configuration validation and threshold behavior persist as ongoing properties after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The classifier-size-output.md contract is updated to replace size_action: reject with size_action: warn; all consumers branching on size_action are verified to handle the new value before the change ships",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time verification task and contract update that must be completed before deployment, not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "CONFIGURATION-REFERENCE.md and dso-config.example.conf include the new review.huge_diff_file_threshold key with default value (20) and valid range (positive integers only)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "documentation and configuration files containing a specific key with defined defaults and constraints represent durable system properties that persist after completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "If fewer than 7 files are eligible for sampling after .test-index and binary/generated file exclusions, sampling is skipped and the commit is treated as low confidence, routing directly to the fallback path",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior and decision rule that applies to all future commits, not a one-time completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
